 $('#research-status').innerHTML=`<span>${esc(labels[r.status]||(r.run_id?'已有研究批次':'尚无已发布研究批次'))}${r.completed_at?' · 整理 '+dt(r.completed_at):''}</span><button class="text-btn" data-view="sources">来源覆盖与更新记录 →</button>`;
 $('#lead-tabs').innerHTML=[['candidate','可继续了解',candidate.length],['target','预算内',target.length],['saved','我的关注',saved.length],['pending','待补资料',filterLeads(all,{filter:'pending'}).length],['all','全部',all.length]].map(([key,label,count])=>`<button data-lead-filter="${key}" aria-pressed="${filter===key}" class="${filter===key?'active':''}">${label}<b>${count}</b></button>`).join('');
