 $('#lead-filter-toggle').textContent='筛选条件'+(active.length?` · ${active.length}`:'');$('#lead-result-count').textContent=`显示 ${visible.length} 条 / 留存 ${all.length} 条`;
 const labelsByKey={region:'区域',platform:'平台',kind:'类型',priceMin:'最低价',priceMax:'最高价',areaMin:'最小面积',areaMax:'最大面积',bathrooms:'双卫',elevator:'电梯',parking:'停车',moveIn:'入住',freshness:'原文日期',progress:'进度',tag:'标签',verification:'条件依据',sort:'排序'};
 $('#lead-filter-chips').innerHTML=active.map(([key,value])=>{const el=$('#'+LEAD_FILTER_IDS[key]),label=el.options?el.options[el.selectedIndex]?.textContent||value:value;return `<button class="filter-chip" data-clear-filter="${key}">${esc(labelsByKey[key]||key)}：${esc(label)} ×</button>`;}).join('');
