function privateFactSelect(key,label,value){return `<label>${label}<select id="lead-verify-${key}"><option value="" ${value==null?'selected':''}>未核实</option><option value="true" ${value===true?'selected':''}>已核实：是</option><option value="false" ${value===false?'selected':''}>已核实：否</option></select></label>`;}
async function openLead(id){
 const x=await api('/api/lead/'+encodeURIComponent(id)),a=x.assessment,c=state.data.settings,f=leadFollowup(x);state.leadId=id;state.leadExpected=JSON.parse(JSON.stringify(x.followup));
 const peers=(state.data.leads||[]).filter(row=>row.lead_id!==id&&row.community===x.community&&row.district===x.district);
 $('#lead-detail-content').innerHTML=`<div class="modal-head"><div><span class="eyebrow">${esc(leadPlatform(x.source_url).name)} · ${x.evidence_kind==='direct_listing'?'单套详情线索':'搜索摘要线索'}</span><h2 id="lead-detail-title">${esc(x.community||'公开信息线索')}</h2></div><button class="icon-btn close-modal" aria-label="关闭线索详情">×</button></div><div class="modal-body">
 <div class="lead-detail-grid"><section><div class="detail-price-strip"><strong>${x.price_wan==null?'价格未知':esc(x.price_wan)+' 万'}</strong><span>${esc(x.district)} · ${x.rooms??'?'}房${x.bathrooms??'?'}卫 · ${x.area_m2??'?'}㎡</span><p>预计总支出 ${wan(a.estimated_purchase_total_yuan)} 万（费用 ${wan(c.estimated_fees_yuan)} 万＋整备 ${wan(c.estimated_refresh_yuan)} 万预留）</p></div>
 <p class="notice amber">${x.evidence_kind==='search_index'?'这是搜索摘要，可能指向列表页；先问清具体房屋和是否仍在售。':'已读到单套广告，当前在售及房况仍需回访核实。'}${leadCaution(x)?' '+esc(leadCaution(x)):''}</p>
 <div class="button-row"><a class="primary" href="${safeURL(x.source_url)}" target="_blank" rel="noopener noreferrer">打开原始来源 ↗</a><button class="secondary" data-peer-search="${esc(x.community)}">同小区 ${peers.length+1} 条线索</button></div>
 <h3>广告与我的核实，分别看</h3><div class="table-wrap"><table class="evidence-compare"><thead><tr><th>关键项</th><th>公开广告</th><th>我的核实</th></tr></thead><tbody>${[['double_bathrooms','至少双卫'],['elevator','有电梯'],['parking_usable','不买车位停车'],['move_in_ready','少量整理入住']].map(([key,label])=>`<tr><td>${label}</td><td>${fact(leadConditionValues(x)[key])}</td><td>${fact(f.verification[key])}</td></tr>`).join('')}<tr><td>当前仍在售</td><td>未确认</td><td>${fact(f.verification.for_sale)}</td></tr></tbody></table></div><p>装修陈述：${esc(x.decoration_claim||'未知')}</p>
 <details class="evidence-metadata" open><summary>来源日期与身份</summary><dl class="lead-evidence"><dt>检索时间</dt><dd>${dt(x.retrieved_at)}</dd><dt>来源更新时间</dt><dd>${x.source_updated_at?dt(x.source_updated_at):'未知'}</dd><dt>来源发布时间</dt><dd>${x.source_published_at?dt(x.source_published_at):'未知'}</dd><dt>身份范围</dt><dd>${x.identity_scope==='source_item'?'来源单套编号，仍需核实具体房号':'列表/搜索条目，不当作唯一房屋'}</dd><dt>历史状态</dt><dd>${x.in_latest_feed?'当前快照收录':'当前快照未收录，不推断下架'} · 留存 ${x.history_count||1} 次检索</dd></dl></details>
 <h3>联系前先问清</h3><ol class="lead-questions">${a.next_checks.map(q=>`<li>${esc(q)}</li>`).join('')}</ol><div class="button-row"><button class="secondary" id="copy-lead-questions">复制待问清单</button><button class="text-btn" id="download-lead-plan">下载看房记录单</button></div><textarea id="lead-copy-text" class="lead-copy-text" readonly aria-label="来源与待问事项">${esc(leadQuestions(x))}</textarea>
 <details class="more-research"><summary>继续补充这个小区的信息</summary><p>以下是手动搜索入口，搜索结果不会自动导入或证明当前在售。</p><div class="button-row">${[['房天下','site:fang.com'],['安居客','site:anjuke.com'],['贝壳 / 链家','site:ke.com OR site:lianjia.com'],['小红书居住体验','site:xiaohongshu.com'],['知乎区域经验','site:zhihu.com']].map(([label,domain])=>`<a class="secondary" href="https://www.bing.com/search?q=${encodeURIComponent(domain+' '+x.district+' '+x.community+' '+(label.includes('体验')||label.includes('经验')?'居住 物业':'三房 二手房'))}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`).join('')}</div></details>
 </section><section class="lead-private"><span class="private-evidence-label">私人记录 · 仅此浏览器保存</span><h3>标记与安排</h3><form id="lead-followup-form"><div class="form-grid"><label>跟进进度<select id="lead-progress-edit">${Object.entries(LEAD_PROGRESS).map(([key,label])=>`<option value="${key}" ${f.progress===key?'selected':''}>${label}</option>`).join('')}</select></label><label class="inline-check"><input id="lead-saved" type="checkbox" ${f.saved?'checked':''}> 关注这条线索</label><label class="wide">标签（用逗号分隔，最多8个）<input id="lead-tags-input" maxlength="210" value="${esc(f.tags.join('，'))}" placeholder="采光好，临街，车位待问"></label><label>下次跟进（北京时间）<input type="datetime-local" id="lead-next-followup" value="${localInput(f.next_followup_at)}"></label><label>约看时间（北京时间）<input type="datetime-local" id="lead-visit-at" value="${localInput(f.visit_at)}"></label><label class="wide">暂缓 / 排除原因<input id="lead-reject-reason" maxlength="500" value="${esc(f.reject_reason)}" placeholder="如：停车无法落实、噪声大"></label><label class="wide">联系 / 看房反馈<textarea id="lead-notes" rows="4" maxlength="16000" placeholder="记录联系结果、采光噪声、房况与下一步">${esc(f.notes)}</textarea></label></div>
 <details class="private-verification" ${f.verification.note?'open':''}><summary>记录我已核实的关键条件</summary><p class="hint">填写确认日期、渠道与依据。这里不修改原广告，也不等于产权核验通过。</p><div class="form-grid">${privateFactSelect('double_bathrooms','至少双卫',f.verification.double_bathrooms)}${privateFactSelect('elevator','有电梯',f.verification.elevator)}${privateFactSelect('parking_usable','不买车位可停车',f.verification.parking_usable)}${privateFactSelect('move_in_ready','少量整理可入住',f.verification.move_in_ready)}${privateFactSelect('for_sale','当前仍在售',f.verification.for_sale)}<label class="wide">核实依据（有结论时必填）<textarea id="lead-verification-note" rows="3" maxlength="4000" placeholder="如：10月23日现场看过两间卫生间；物业确认可月租，价格待确认">${esc(f.verification.note)}</textarea></label></div>${f.verification.updated_at?`<p class="hint">记录于 ${dt(f.verification.updated_at)}</p>`:''}</details>
 <button type="submit" class="primary" id="save-lead-followup">保存跟进</button></form><div class="button-row"><button class="secondary" id="export-lead-calendar" ${!f.visit_at?'disabled':''}>下载约看日历</button><button class="text-btn" id="promote-lead">${f.linked_offer_id?'打开核验档案':'转入私人核验档案'}</button></div><p class="hint">日历文件只记录你的安排，不会向中介发送预约。转入档案会带入广告字段和原检索日期，供你继续核对。</p></section></div></div>`;
 const modal=$('#lead-modal');if(!modal.open)modal.showModal();
}
async function saveLeadFollowup(){
 const verification={note:$('#lead-verification-note').value};for(const key of ['double_bathrooms','elevator','parking_usable','move_in_ready','for_sale']){const value=$('#lead-verify-'+key).value;verification[key]=value===''?null:value==='true';}
 await api('/api/lead-followup',{lead_id:state.leadId,expected_followup:state.leadExpected,saved:$('#lead-saved').checked,notes:$('#lead-notes').value,progress:$('#lead-progress-edit').value,tags:$('#lead-tags-input').value.split(/[,，\n]/).map(x=>x.trim()).filter(Boolean),next_followup_at:readLocalTime($('#lead-next-followup').value),visit_at:readLocalTime($('#lead-visit-at').value),reject_reason:$('#lead-reject-reason').value,verification});
 await load();await openLead(state.leadId);toast('标记、安排和核实依据已保存。');
}
async function promoteCurrentLead(){
 if(!browserMode)throw Error('公开线索的私人档案目前在网页版管理。');
 // Preserve the open form first; validation or a stale snapshot must stop promotion.
 await saveLeadFollowup();
 const result=await api('/api/lead-promote',{lead_id:state.leadId});$('#lead-modal').close();await load();await setView('library');await openDetail(result.offer_id);toast(result.created?'广告资料已带入私人档案，待你逐项核实。':'已打开关联档案，保留你的后续修改。');
}
function followupLeads(filter='active'){
 const chinaDay=new Date(Date.now()+8*3600000).toISOString().slice(0,10),todayEnd=Date.parse(chinaDay+'T23:59:59.999+08:00');
 return (state.data.leads||[]).filter(x=>{const f=leadFollowup(x),tracked=f.saved||f.progress!=='new'||f.notes||f.visit_at||f.next_followup_at||f.tags.length||f.verification.note||['elevator','double_bathrooms','parking_usable','move_in_ready','for_sale'].some(k=>typeof f.verification[k]==='boolean');return tracked&&(filter==='all'||filter==='active'&&f.progress!=='rejected'||filter==='due'&&f.progress!=='rejected'&&[f.next_followup_at,f.progress==='visit'?f.visit_at:null].some(t=>t&&Date.parse(t)<=todayEnd)||f.progress===filter);}).sort((a,b)=>{const next=x=>{const f=leadFollowup(x);return Math.min(...[f.next_followup_at,f.progress==='visit'?f.visit_at:null].filter(Boolean).map(Date.parse),Infinity);};return next(a)-next(b)||String(a.community||'').localeCompare(String(b.community||''),'zh-CN')||a.lead_id.localeCompare(b.lead_id);});
}
function renderFollowups(){
 const active=followupLeads(),due=followupLeads('due'),visits=followupLeads('visit');
 $('#followup-summary').innerHTML=`<button data-followup-filter="due"><strong>${due.length}</strong><span>今天及逾期待办</span></button><button data-followup-filter="visit"><strong>${visits.length}</strong><span>已约看</span></button><button data-followup-filter="active"><strong>${active.length}</strong><span>正在跟进</span></button>`;
 $('#followup-tabs').innerHTML=[['active','正在跟进'],['due','今天待办'],['contact','待联系'],['visit','已约看'],['visited','已看房'],['hold','暂缓'],['rejected','已排除'],['all','全部']].map(([key,label])=>`<button data-followup-filter="${key}" class="${state.followupFilter===key?'active':''}" aria-pressed="${state.followupFilter===key}">${label}</button>`).join('');
 const rows=followupLeads(state.followupFilter);$('#followup-list').innerHTML=rows.length?rows.map(leadCard).join(''):'<div class="empty"><strong>这里还没有跟进记录</strong><p>在找房列表关注房源，或标记待联系、填写约看时间。返回这里继续下一步。</p><button class="primary" data-view="overview">去找房线索</button></div>';
}
function leadComparisonText(){return (state.data.leads||[]).filter(x=>state.leadSelected.has(x.lead_id)).map(x=>{const f=leadFollowup(x);return `${x.community} / ${x.district}\n广告 ${x.price_wan??'未知'} 万；预计总支出 ${wan(x.assessment.estimated_purchase_total_yuan)} 万\n${x.rooms??'?'}房${x.bathrooms??'?'}卫 / ${x.area_m2??'?'}㎡\n原文日期 ${leadSourceDate(x)||'未知'}；检索 ${dt(x.retrieved_at)}\n进度 ${LEAD_PROGRESS[f.progress]}；标签 ${f.tags.join('、')||'暂无'}\n待核 ${[leadCaution(x),...x.assessment.pending].filter(Boolean).join('；')}\n我的笔记 ${f.notes||'暂无'}\n来源 ${x.source_url}`;}).join('\n\n---\n\n');}
function renderLeadComparison(){
 const rows=(state.data.leads||[]).filter(x=>state.leadSelected.has(x.lead_id));
 if(rows.length<2){$('#lead-comparison').innerHTML=`<div class="empty"><strong>已选 ${rows.length} 条，至少选择2条</strong><p>回到找房列表勾选“对比”，最多4条。无需先重复收录到私人档案。</p><button class="primary" data-view="overview">选择房源</button></div>`;return;}
 const fields=[['广告报价',x=>(x.price_wan??'未知')+' 万'],['预计总支出',x=>wan(x.assessment.estimated_purchase_total_yuan)+' 万（预留估算）'],['区域 / 户型 / 面积',x=>`${x.district} / ${x.rooms??'?'}房${x.bathrooms??'?'}卫 / ${x.area_m2??'?'}㎡`],['广告称电梯 / 停车 / 入住',x=>[x.elevator,x.parking_usable,x.move_in_ready].map(fact).join(' / ')],['我的核实：双卫 / 电梯 / 停车',x=>{const v=leadFollowup(x).verification;return[v.double_bathrooms,v.elevator,v.parking_usable].map(fact).join(' / ');}],['当前在售（我的核实）',x=>fact(leadFollowup(x).verification.for_sale)],['装修陈述',x=>x.decoration_claim||'未知'],['关键待核',x=>[leadCaution(x),...x.assessment.failures,...x.assessment.pending].filter(Boolean).join('；')||'回访确认在售与房况'],['来源类型 / 原文日期',x=>(x.evidence_kind==='direct_listing'?'单套详情':'搜索摘要')+' / '+(leadSourceDate(x)||'未知')],['进度 / 标签',x=>{const f=leadFollowup(x);return LEAD_PROGRESS[f.progress]+' / '+(f.tags.join('、')||'暂无');}],['看房安排',x=>dt(leadFollowup(x).visit_at)],['联系与看房反馈',x=>leadFollowup(x).notes||'暂无']];
 $('#lead-comparison').innerHTML=`<div class="table-wrap"><table class="compare"><thead><tr><th>比较维度</th>${rows.map(x=>`<th>${esc(x.community)}<button class="text-btn" data-lead-detail="${esc(x.lead_id)}">详情 / 标记</button><button class="text-btn" data-remove-lead-comparison="${esc(x.lead_id)}">移除</button></th>`).join('')}</tr></thead><tbody>${fields.map(([label,fn])=>`<tr><td>${label}</td>${rows.map(x=>`<td>${esc(fn(x))}</td>`).join('')}</tr>`).join('')}<tr><td>原始来源</td>${rows.map(x=>`<td><a href="${safeURL(x.source_url)}" target="_blank" rel="noopener noreferrer">${esc(leadPlatform(x.source_url).name)} ↗</a></td>`).join('')}</tr></tbody></table></div>`;
}
async function copyText(text){if(navigator.clipboard?.writeText){try{await navigator.clipboard.writeText(text);toast('已复制到剪贴板。');return;}catch{}}const textarea=document.createElement('textarea');textarea.value=text;document.body.append(textarea);textarea.select();const ok=document.execCommand('copy');textarea.remove();if(!ok)throw Error('剪贴板不可用，请下载记录单后复制。');toast('已复制到剪贴板。');}
function downloadText(name,text,type='text/plain;charset=utf-8'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function leadVisitPlan(x){const f=leadFollowup(x);return '# '+x.community+' · 看房记录单\n\n'+leadQuestions(x)+'\n\n## 现场记录\n- 具体房号（仅私人保存）：\n- 朝向 / 采光 / 遮挡：\n- 临街与邻里噪声：\n- 渗漏 / 水压 / 电路 / 门窗：\n- 两个卫生间实际位置与使用：\n- 停车位置 / 月租 / 通行限制：\n- 入住前必做整备与估价：\n- 下一步与截止时间：\n\n进度：'+LEAD_PROGRESS[f.progress]+'\n标签：'+f.tags.join('、')+'\n';}
function leadCalendar(x){
 const visit=leadFollowup(x).visit_at;if(!visit)throw Error('先填写并保存约看时间。');
 const clean=value=>String(value).replace(/\\/g,'\\\\').replace(/\r\n|\r|\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;'),stamp=value=>new Date(value).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z$/,'Z');
 return ['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Home Watch//Private visit plan//ZH','CALSCALE:GREGORIAN','BEGIN:VEVENT','UID:'+clean(x.lead_id)+'@homewatch.local','DTSTAMP:'+stamp(Date.now()),'DTSTART:'+stamp(visit),'DTEND:'+stamp(Date.parse(visit)+3600000),'SUMMARY:'+clean('看房 · '+x.community),'DESCRIPTION:'+clean('个人安排，尚需自行确认预约。\n'+leadQuestions(x)),'LOCATION:'+clean(x.district+' '+x.community),'END:VEVENT','END:VCALENDAR',''].join('\r\n');
}

function renderOverview(){if(!state.data)return;const d=state.data,c=d.settings;const stats=[['已收录房源 / 线索',d.offers.length,'条','并非全网房源数量'],[c.budget_basis==='purchase_total'?'预计支出在目标内':'挂牌房价在目标内',d.offers.filter(x=>x.assessment.budget_band==='目标预算内'&&!x.assessment.failures.length&&x.assessment.status!=='非在售').length,'条','仍需核实停车、房况与产权'],['定金 / 签约前检查未齐',d.offers.filter(x=>x.assessment.unresolved.length).length,'条','未核验不能被匹配分抵消'],[browserMode?'个人后台自动源':'已启用自动源',d.active_sources,'个',browserMode?'个人来源需打开网页手动同步':d.active_sources?'以来源健康状态为准':'尚未连接，不会自动发现新房源']];$('#stats').innerHTML=stats.map(([label,value,unit,note])=>`<div class="stat"><div class="stat-label">${esc(label)}</div><div class="stat-value">${value}<small>${unit}</small></div><div class="stat-note">${esc(note)}</div></div>`).join('');$('#strategy-text').textContent=`目标${c.budget_basis==='purchase_total'?'总支出':'房价'} ${wan(c.budget_yuan)} 万 · 弹性至 ${wan(c.stretch_yuan)} 万（暂定） · 首付上限 ${wan(c.max_down_payment_yuan)} 万 · 费用＋整备预留 ${wan(c.estimated_fees_yuan+c.estimated_refresh_yuan)} 万 · 三房双卫`;const offers=filtered();$('#result-count').textContent=offers.length+' 条结果';$('#cards').innerHTML=offers.length?offers.map(card).join(''):`<div class="empty"><strong>暂时没有符合当前筛选的线索</strong><p>先粘贴一套房源描述或导入 CSV / JSON，再逐项核实三房双卫、停车和全屋现状。未知不会自动当作符合。</p></div>`;$('#duplicate-notice').innerHTML=d.duplicates.length?`<div class="notice amber">发现 ${d.duplicates.length} 组疑似重复。${d.duplicates.slice(0,4).map(x=>esc(x.community)).join('、')}：同小区、同房数、面积接近只是线索；核实后可填写相同“关联组编号”，报价历史仍按平台独立保留。</div>`:'';}
function card(x){const a=x.assessment,pending=[...a.failures,...x.data_issues,...a.pending];const bclass=a.status==='不符合'?'red':a.status==='核验已填齐'?'green':'amber';const shape=`${x.rooms??'?'}房${x.bathrooms??'?'}卫 · ${x.area_m2??'面积待补充'}${x.area_m2?'㎡':''}`;const tags=[['电梯',x.elevator],['停车',x.parking_usable],['可入住',x.move_in_ready],['年轻化',x.young_style]];return `<article class="card ${a.priority?'priority':''}" data-id="${x.id}"><div class="card-top"><span class="pill ${a.priority?'green':''}">${a.priority?'重点观察':'普通观察'}</span><span class="card-source">${esc(x.source)} · ${x.source_kind?.includes('摘要')?'摘要线索':'观测记录'}</span></div><h3>${esc(x.community||x.title)}</h3><div class="card-sub">${esc(x.district||'行政归属待核实')} · ${esc(x.stage)}</div><div class="price-line"><div class="price">${wan(x.price_yuan)}${x.price_yuan?'<small>万元</small>':''}</div><span class="pill ${a.budget_band==='弹性观察'?'amber':''}">${esc(a.budget_band)}</span></div><p class="budget-estimate">预计购房总支出 <strong>${wan(a.estimated_purchase_total_yuan)} 万</strong> · 费用与整备按预留估算</p><div class="facts">${esc(shape)} <span class="unit-price">${x.area_m2&&x.price_yuan?' / '+yuan(x.price_yuan/x.area_m2)+'元/㎡':''}</span></div><div class="tags">${tags.map(([label,value])=>`<span class="pill ${value===true?'green':value===false?'red':''}">${label}${value===true?'：记录有':value===false?'：不符合':'待核实'}</span>`).join('')}</div><hr><div class="next-step"><strong>下一步：</strong>${esc((pending[0]||a.unresolved[0]||'安排现场复看').slice(0,95))}</div><div class="card-meta"><span>观测 ${day(x.observed_at)}${a.stale?' · 已过期':''}</span><span class="score">偏好 ${a.score}/100</span></div><div class="card-foot"><label><input type="checkbox" data-compare="${x.id}" ${state.selected.has(x.id)?'checked':''}> 对比</label><span class="pill ${bclass}">${esc(a.status)}</span><button class="primary" data-detail="${x.id}">核验与跟进</button></div></article>`;}
function renderAlerts(){const data=state.data.alerts;$('#alerts-list').innerHTML=data.length?data.map(a=>`<div class="alert-item ${a.read_at?'read':''}"><div><span class="pill ${a.kind.includes('下降')?'green':'amber'}">${esc(a.kind)}</span><p>${esc(a.message)}</p><small>${dt(a.created_at)}${a.read_at?' · 已读':''}</small>${a.confirmation?`<p class="hint">人工确认依据：${esc(a.confirmation)}</p>`:''}</div><div class="alert-actions">${a.offer_id?`<button class="secondary" data-detail="${esc(a.offer_id)}">看房源</button>`:''}${!a.read_at?`<button class="text-btn" data-read="${a.id}">标为已读</button>`:''}${a.kind.includes('待确认')?`<button class="text-btn" data-confirm="${a.id}">记录确认依据</button>`:''}</div></div>`).join(''):`<div class="empty"><strong>还没有真实的变更记录</strong><p>初始线索不伪装为刚挂牌；至少两次同源观测才能形成报价变化。</p></div>`;}
function renderCompare(){const offers=state.data.offers.filter(x=>state.selected.has(x.id));if(offers.length<2){$('#compare-table').innerHTML=`<div class="empty"><strong>已选择 ${offers.length} 条，至少需要2条</strong><p>前往“我的房源”，在卡片下方勾选“对比”；最多4条。</p></div>`;return;}const rows=[['预计购房总支出',x=>wan(x.assessment.estimated_purchase_total_yuan)+' 万（按预留估算）'],['挂牌报价',x=>wan(x.price_yuan)+' 万'],['建筑面积',x=>x.area_m2==null?'待补充':x.area_m2+'㎡'],['户型',x=>(x.rooms??'?')+'房'+(x.bathrooms??'?')+'卫'],['区域',x=>x.district||'待核实'],['电梯',x=>fact(x.elevator)],['停车可落实',x=>fact(x.parking_usable)],['少量整理入住',x=>fact(x.move_in_ready)],['年轻化装修',x=>fact(x.young_style)],['生活配套',x=>fact(x.amenities)],['学区已核实',x=>fact(x.school_verified)],['来源状态',x=>x.status],['偏好匹配分',x=>x.assessment.score+'/100，不代表安全'],['核验完成',x=>x.assessment.verified_checks+'/'+x.assessment.total_checks],['最需解决',x=>(x.assessment.failures.concat(x.data_issues,x.assessment.pending,x.assessment.unresolved).slice(0,3)).join('；')],['当前流程',x=>x.stage],['观测时间',x=>dt(x.observed_at)],['跟进笔记',x=>x.notes||'暂无']];$('#compare-table').innerHTML=`<div class="table-wrap"><table class="compare"><thead><tr><th>比较维度</th>${offers.map(x=>`<th>${esc(x.community||x.title)}<br><button class="text-btn" data-detail="${x.id}">查看核验</button></th>`).join('')}</tr></thead><tbody>${rows.map(([label,fn])=>`<tr><td>${esc(label)}</td>${offers.map(x=>`<td>${esc(fn(x))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function checkHTML(k,oid=''){const clear=['通过','不适用'].includes(k.status);return `<details class="guide-item" data-check="${esc(k.id)}"><summary><span>${esc(k.title)}</span><span class="pill">${esc(k.stage)}</span><span class="pill ${k.status==='有风险'?'red':clear?'green':'amber'}">${esc(oid?k.status:(k.before_contract?'定金 / 签约前必查':'阶段核验'))}</span></summary><div class="guide-body"><p><strong>为什么查：</strong>${esc(k.why)}</p><p><strong>具体怎么查：</strong>${esc(k.ask)}</p><p><strong>应保存的依据：</strong>${esc(k.evidence_hint)}</p>${k.source_url?`<p><a href="${safeURL(k.source_url)}" target="_blank" rel="noopener noreferrer">核对参考依据</a> · ${esc(k.basis)}</p>`:`<p class="hint">${esc(k.basis)}</p>`}${k.expires_days?`<p class="hint">本工具的复核提醒间隔为${k.expires_days}天，并非法律规定的有效期；签约/过户前仍应复查。</p>`:''}${oid?`<form class="check-form" data-check-form="${esc(k.id)}"><textarea name="evidence" rows="3" placeholder="填写核实时间、渠道、结论与证据编号；不要保存完整身份证/银行卡">${esc(k.evidence)}</textarea><div class="button-row"><select name="status" aria-label="${esc(k.title)}状态">${['待核实','通过','有风险',...(k.allow_na?['不适用']:[]),'待复核'].map(v=>`<option ${v===k.status?'selected':''}>${v}</option>`).join('')}</select><button type="submit" class="secondary">保存核验依据</button></div><small class="muted">上次记录：${dt(k.updated_at)}</small></form>`:''}</div></details>`;}
function renderGuide(){const k=state.data.knowledge;$('#guide-list').innerHTML=k.checks.map(x=>checkHTML(x)).join('');$('#policy-cards').innerHTML=k.policies.map(p=>`<article class="policy-card"><span class="pill ${p.status.includes('已查到')?'green':'amber'}">${esc(p.status)}</span><h3>${esc(p.title)}</h3><p>${esc(p.text)}</p><small>资料核对：${esc(p.verified_on)} · ${esc(p.scope)}</small>${p.url?`<div><a href="${safeURL(p.url)}" target="_blank" rel="noopener noreferrer">查看依据 / 线索</a></div>`:''}</article>`).join('');}
function renderSources(){
 renderResearchChannels(state.data);
 const d=state.data,h=d.source_health;
 if(browserMode)renderPublicFeedHealth(d);
 $('#source-health').innerHTML=d.sources.length?d.sources.map(s=>{
  const x=h[s.id]||{},latestOld=x.newest_observed_at&&(Date.now()-new Date(x.newest_observed_at).getTime()>d.settings.stale_hours*3600000);
  const warnings=[...(x.warnings||[])];if(latestOld&&!warnings.some(w=>w.includes('过期')))warnings.push('来源中的最新观测现已过期，下载成功不等于新鲜房源');
  const status=!s.enabled?'未启用':!s.authorized?'未确认权限':x.paused?'失败后暂停':x.error?'同步失败':x.last_success?(warnings.length?'已读取 · 数据需复核':'已读取 · 真实性未核验'):'尚未同步';
  const good=x.last_success&&s.enabled&&!x.error&&!warnings.length;
  return `<div class="source-row"><div><strong>${esc(s.name||s.id)}</strong><p>${esc(s.type==='json_file'?(browserMode?'浏览器文件':'本地文件'):'授权HTTPS接口')} · ${browserMode?'仅手动同步':'每'+esc(s.interval_minutes)+'分钟'}</p><p>${esc(s.id)}</p></div><div><p>最近成功读取：${dt(x.last_success)}</p><p>源内最新观测：${dt(x.newest_observed_at)}</p><p>${x.result?'最近返回 '+(x.row_count??'?')+' 条 / 新增 '+(x.result.new??0)+' / 变化 '+(x.result.changed??0)+' / 旧记录忽略 '+(x.result.older_ignored??0):'尚无成功结果'}${x.error?'；'+esc(x.error):''}</p>${warnings.map(w=>`<p class="warning">${esc(w)}</p>`).join('')}</div><div><span class="pill ${x.error?'red':good?'green':'amber'}">${status}</span><p>${x.next_run?'下次计划：'+dt(x.next_run):'不代表已连接房产平台'}</p><div class="button-row"><button class="secondary" data-source-edit="${esc(s.id)}">编辑</button><button class="secondary" data-source-run="${esc(s.id)}" ${!s.enabled?'disabled':''}>单独同步</button></div></div></div>`;
 }).join(''):'<div class="notice amber">你还没有添加个人导入源。公开研究线索仍可在“找房线索”查看；这里可添加自己的文件或授权数据。</div>';
 if(h._mail)$('#source-health').innerHTML+=`<div class="notice ${h._mail.error?'amber':''}">邮件投递：${esc(h._mail.error||('上次发送日期 '+h._mail.sent_day))}</div>`;
 $('#channels').innerHTML=d.knowledge.channels.map(s=>`<article class="policy-card"><span class="pill">${esc(s.status)}</span><h3>${esc(s.name)}</h3><p>${esc(s.note)}</p>${s.url?`<a href="${safeURL(s.url)}" target="_blank" rel="noopener noreferrer">打开人工浏览入口</a>`:''}${s.terms_url?` · <a href="${safeURL(s.terms_url)}" target="_blank" rel="noopener noreferrer">服务协议</a>`:''}</article>`).join('');
 if(!state.sourceDirty)$('#sources-editor').value=JSON.stringify(d.sources,null,2);
}

function renderSettings(){if(state.settingsDirty)return;const f=$('#settings-form'),s=state.data.settings,m={budget_basis:s.budget_basis,estimated_fees_wan:s.estimated_fees_yuan/10000,estimated_refresh_wan:s.estimated_refresh_yuan/10000,budget_wan:s.budget_yuan/10000,stretch_wan:s.stretch_yuan/10000,down_wan:s.max_down_payment_yuan/10000,stale_hours:s.stale_hours,drop_wan:s.price_alert_yuan/10000,price_alert_pct:s.price_alert_pct,digest_hour:s.digest_hour,monitor_until:s.monitor_until,priority_communities:s.priority_communities.join('\n')};for(const[k,v]of Object.entries(m))f.elements[k].value=v;}
async function calculate(){const data=Object.fromEntries(new FormData($('#finance-form'))),r=await api('/api/calculate',data);const rows=[['计划贷款本金',wan(r.loan_yuan)+' 万元'],['房款＋交易费用＋整备',wan(r.purchase_total_yuan)+' 万元'],['首付＋交易费用＋整备',wan(r.upfront_yuan)+' 万元'],['加上所填应急金的现金需求',wan(r.cash_with_reserve_yuan)+' 万元'],['当前计划下现金缺口',r.cash_gap_yuan==null?'请填写全部可用现金':wan(r.cash_gap_yuan)+' 万元'],['相对所填可贷额度的缺口',r.loan_gap_yuan==null?'尚未填写银行确认额度':wan(r.loan_gap_yuan)+' 万元'],['全期利息（利率不变假设）',wan(r.interest_yuan)+' 万元']];$('#finance-result').innerHTML=`<span class="eyebrow">等额本息 · 情景测算</span><h2>每月还款</h2><div class="big-number">${yuan(r.monthly_yuan)}<small>元 / 月</small></div><p class="muted">本金、利率与期限任一变化，结果会不同。</p>${rows.map(([k,v])=>`<div class="finance-row"><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`).join('')}${r.adjusted_cash_gap_yuan!=null?`<div class="finance-row warning"><span>考虑贷款不足后的总现金缺口</span><strong>${wan(r.adjusted_cash_gap_yuan)} 万元</strong></div>`:''}<p class="hint">${esc(r.warning)}${Number(data.down_wan)*10000>state.data.settings.max_down_payment_yuan?' 当前首付超过你设置的首付能力上限。':''}</p>`;}
async function renderDigest(refresh=false){const r=await api('/api/digest',refresh?{}:undefined);$('#digest-body').textContent=r.body;}
function assignForm(f,data){for(const[k,v]of Object.entries(data)){const el=f.elements[k];if(!el)continue;el.value=Array.isArray(v)?v.join('\n'):v===true?'true':v===false?'false':v??'';}}
async function openOffer(id=null){state.editId=id;const f=$('#offer-form');f.reset();$$('.inline-errors',$('#offer-modal')).forEach(x=>x.remove());$('#paste-text').value='';$('#parse-warnings').textContent='';for(const k of ['source','source_item_id','url'])f.elements[k].readOnly=!!id;$('#paste-helper').hidden=!!id;$('#offer-modal-title').textContent=id?'记录这套房的新观测':'收录一条房源';if(id){const x=await api('/api/offer/'+id);assignForm(f,{...x,price_wan:x.price_yuan==null?'':x.price_yuan/10000,observed_at:''});}$('#offer-modal').showModal();}
async function saveOffer(){const f=$('#offer-form'),d=Object.fromEntries(new FormData(f));d.price_yuan=d.price_wan===''?null:Math.round(Number(d.price_wan)*10000);delete d.price_wan;d.data_issues=d.data_issues.split('\n').map(x=>x.trim()).filter(Boolean);for(const x of ['elevator','parking_usable','move_in_ready','young_style','amenities','school_verified','in_excluded_zone'])d[x]=d[x]===''?null:d[x]==='true';const r=state.editId?await api('/api/observe',{id:state.editId,fields:d}):await api('/api/import',{rows:[d]});$('#offer-modal').close();await load();if(!state.editId)await setView('library');if($('#detail-modal').open)await openDetail(state.detailId);toast(`新增 ${r.new} · 更新 ${r.changed} · 未变 ${r.unchanged} · 旧观测忽略 ${r.older_ignored} · 冲突 ${r.conflicts}`);}
async function openDetail(id){state.detailId=id;const x=await api('/api/offer/'+id),a=x.assessment,problems=[...a.critical,...a.failures,...x.data_issues,...a.pending];const history=x.history.slice().reverse();$('#detail-content').innerHTML=`<div class="modal-head"><div><span class="eyebrow">${esc(x.source)} · ${esc(x.source_item_id||'来源链接识别')}</span><h2>${esc(x.community||x.title)}</h2><p class="detail-title-sub">首次收录 ${dt(x.first_seen)} · 最新来源观测 ${dt(x.observed_at)}</p></div><button class="icon-btn close-modal" aria-label="关闭详情">×</button></div><div class="detail-layout"><div class="detail-main"><div class="panel"><div class="detail-facts"><div><span>挂牌总价</span><strong>${wan(x.price_yuan)} 万元</strong></div><div><span>户型 / 面积</span><strong>${x.rooms??'?'}房${x.bathrooms??'?'}卫 / ${x.area_m2??'?'}㎡</strong></div><div><span>定金 / 签约前检查</span><strong>${a.unresolved.length} 项未齐</strong></div></div><div class="score-grid">${Object.entries(a.score_breakdown).map(([k,v])=>`<span>${esc(k)} ${v}</span>`).join('')}</div><p class="hint">偏好合计 ${a.score}/100；这是规则评分，不是价格评估或交易安全证明。${a.stale?'本条观测已过期。':''}</p><div class="button-row">${x.url?`<a class="secondary" href="${safeURL(x.url)}" target="_blank" rel="noopener noreferrer">打开原始来源</a>`:''}<button class="primary" data-edit="${x.id}">记录新报价 / 更新事实</button></div></div>${problems.length?`<div class="notice amber"><strong>还不能直接作为购房结论</strong><div class="critical-list">${problems.map(t=>'• '+esc(t)).join('<br>')}</div></div>`:''}<h3>逐项核验，保存依据</h3>${x.checks.map(k=>checkHTML(k,id)).join('')}</div><aside class="detail-side"><div class="panel"><h3>跟进与决定</h3><label for="detail-stage">当前阶段</label><select id="detail-stage">${state.data.stages.map(s=>`<option ${s===x.stage?'selected':''}>${s}</option>`).join('')}</select><label for="detail-group">同一物理房屋的关联组（核实后填写）</label><input id="detail-group" value="${esc(x.group_id)}" placeholder="例如：DBW-候选01"><label for="detail-notes">跟进笔记 / 下次行动</label><textarea id="detail-notes" rows="7" placeholder="看房结论、联系时间、整备预算、需要追问什么…">${esc(x.notes)}</textarea><button class="primary" id="save-workflow">保存跟进</button><p id="workflow-error" class="inline-errors"></p><p class="hint">推进到付定金、待签约及之后，系统会检查关键核验。记录已完成不代表系统为交易背书。</p></div><div class="panel"><h3>报价与观测历史</h3><p class="hint">同一平台报价记录；无变化的重复内容不重复存快照。冲突快照不代表已接受的变价。</p><div class="detail-history"><table><thead><tr><th>观测时间</th><th>报价 / 万</th><th>状态</th></tr></thead><tbody>${history.map(h=>`<tr><td>${dt(h.observed_at)}</td><td>${wan(h.data.price_yuan)}${history.filter(t=>t.observed_at===h.observed_at).length>1?'<span class="snapshot-note">同时间有冲突</span>':''}</td><td>${esc(h.data.status)}</td></tr>`).join('')}</tbody></table></div></div><div class="panel"><h3>原始描述</h3><p class="hint">${esc(x.source_kind)} · ${esc(x.floor||'楼层待补充')}</p><div class="raw-text">${esc(x.raw_text||'暂无原始描述')}</div></div><div class="panel"><h3>最近操作留痕</h3>${x.audit.length?x.audit.slice(0,8).map(t=>`<div class="audit-item"><strong>${esc(t.action)}</strong> · ${dt(t.created_at)}<p>${esc(t.detail)}</p></div>`).join(''):'<p class="hint">尚无人工核验或流程记录。</p>'}</div></aside></div>`;if(!$('#detail-modal').open)$('#detail-modal').showModal();}
// Delegated actions survive re-rendering; all writes go through CSRF-protected POST.
