function sourceTypeChanged(){const remote=$('#source-type').value==='json_https';$('#source-path-row').hidden=remote;$('#source-url-row').hidden=!remote;$('#source-token-row').hidden=browserMode||!remote;}
function openSource(id=null){const f=$('#source-form');f.reset();state.sourceEditId=id;const old=state.data.sources.find(x=>x.id===id);if(browserMode)f.elements.token_env.value='';if(old){assignForm(f,old);f.elements.authorized.checked=old.authorized===true;f.elements.enabled.checked=old.enabled===true;}f.elements.id.readOnly=!!id;$('#source-title').textContent=id?'编辑数据源':'添加授权数据源';sourceTypeChanged();$('#source-modal').showModal();}
$('#source-type').onchange=sourceTypeChanged;
