$('#upload-source').onclick=()=>{$('#inbox-form').reset();$('#inbox-modal').showModal();};
$('#inbox-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>2*1024*1024){toast('文件不得超过2MB',true);return;}const form=$('#inbox-form');form.elements.text.value=await f.text();form.elements.format.value=f.name.toLowerCase().endsWith('.csv')?'csv':'json';const stem=f.name.replace(/\.(csv|json)$/i,'').replace(/[^A-Za-z0-9_-]/g,'_');form.elements.filename.value=(/^[A-Za-z0-9]/.test(stem)?stem:'feed-'+stem)+'.json';};
$('#inbox-form').onsubmit=e=>{e.preventDefault();task($('button[type=submit]',e.target),async()=>{const d=Object.fromEntries(new FormData(e.target));d.overwrite=e.target.elements.overwrite.checked;const r=await api('/api/inbox',d);$('#inbox-modal').close();toast(`已保存 ${r.filename}，共${r.row_count}条；配置来源后再同步。`);});};
$('#source-form').onsubmit=e=>{e.preventDefault();task($('button[type=submit]',e.target),async()=>{const f=e.target,d=Object.fromEntries(new FormData(f));d.enabled=f.elements.enabled.checked;d.authorized=f.elements.authorized.checked;d.interval_minutes=Number(d.interval_minutes);if(d.type==='json_file'){d.url='';d.token_env='';}else d.path='';const sources=state.data.sources.filter(x=>x.id!==(state.sourceEditId||''));if(sources.some(x=>x.id===d.id))throw Error('来源ID已存在，请用编辑功能');if(browserMode)d.token_env='';sources.push(d);await api('/api/sources',{sources});state.sourceDirty=false;$('#source-modal').close();await load();toast(browserMode?'数据源已保存；仅在网页打开时手动同步。':'数据源已保存；请单独同步确认结果。');});};
