// GitHub Pages uses a local browser ledger; the Python server keeps its original API.
function renderResearchChannels(d){
 const channels=d.knowledge.research_channels||d.knowledge.channels||[],categories=[...new Set(channels.map(x=>x.category||'更多渠道'))];
 $('#research-channels').innerHTML=categories.map(category=>`<section class="channel-group"><h3>${esc(category)}</h3><div class="channel-grid">${channels.filter(x=>(x.category||'更多渠道')===category).map(x=>`<article class="channel-card"><div><h4>${esc(x.name)}</h4><span class="pill">${esc(x.status||'手动查看入口')}</span></div><p>${esc(x.use_for||x.note||'打开原文继续核实。')}</p>${x.access_note?`<p class="hint">${esc(x.access_note)}</p>`:''}${x.queries?.length?`<details><summary>建议搜索词</summary><ul>${x.queries.map(q=>`<li>${esc(q.replace(/\{region\}/g,'吉州区 / 吉安县'))}</li>`).join('')}</ul></details>`:''}${safeURL(x.url)?`<a class="channel-link" href="${safeURL(x.url)}" target="_blank" rel="noopener noreferrer">前往${esc(x.name)} ↗</a>`:''}</article>`).join('')}</div></section>`).join('');
}
function sourceStatus(results){
 const statuses=results.map(x=>x.status||x.state||'unknown');
 if(!statuses.length)return {label:'仅有留存线索',tone:'neutral'};
 if(statuses.every(x=>x==='success'))return {label:'本批已读取',tone:'green'};
 if(statuses.some(x=>x==='success'||x==='partial'))return {label:'本批部分可读',tone:'amber'};
 if(statuses.every(x=>x==='blocked'))return {label:'访问受限',tone:'amber'};
 if(statuses.some(x=>x==='failed'))return {label:'本批读取失败',tone:'red'};
 return {label:'本批尚待核实',tone:'amber'};
}
function renderPublicFeedHealth(d){
 const local=d.feed_status||{},monitoring=d.published_monitoring||{};
 const feed={...local,generated_at:d.public_feed_generated_at,state:monitoring.state,reason:monitoring.reason},health=d.public_source_health||{},sources=d.public_sources||[];
 const research=d.research||{};
 const groups=new Map(),ensure=value=>{const p=leadPlatform(value);if(!groups.has(p.id))groups.set(p.id,{...p,results:[],leads:[]});return groups.get(p.id);};
 for(const x of research.source_results||[])ensure(x.source_domain||x.source_id||'unknown').results.push(x);
 for(const x of d.leads||[])ensure(x.source_url).leads.push(x);
 const stateLabel=research.status==='failed'?'本次检索失败 · 保留历史':{active:'已发布',success:'已发布',healthy:'已发布',degraded:'已发布 · 部分来源待补充',failed:'本批失败 · 保留历史',empty:'等待公开线索'}[feed.state]||'公开快照';
 $('#public-feed-health').innerHTML=`<section class="publication-overview"><div><span class="eyebrow">公开数据覆盖</span><h3>${esc(stateLabel)}</h3><p>最近整理 ${dt(research.completed_at)} · 当前留存 ${(d.leads||[]).length} 条广告线索</p></div><p class="hint">按实际研究批次更新<br>读取成功仍需确认在售情况</p></section>${feed.error?`<div class="notice red">${esc(feed.error)}。已保留现有线索与个人记录。</div>`:''}<div class="platform-health-grid">${[...groups.values()].map(group=>{const s=sourceStatus(group.results),current=group.leads.filter(x=>x.in_latest_feed).length;return `<article class="platform-health-card"><div class="platform-health-heading"><h3>${esc(group.name)}</h3><span class="pill ${s.tone}">${s.label}</span></div><div class="source-count"><strong>${group.leads.length}</strong><span>条留存线索 · 当前快照 ${current} 条</span></div><p class="source-detail-counts">${group.leads.filter(x=>x.evidence_kind==='direct_listing').length} 条曾读到单套详情 · ${group.leads.filter(x=>x.source_updated_at||x.source_published_at).length} 条有原文日期</p><p>${s.tone==='green'?'已取得公开内容，具体房屋仍需回访确认。':s.label==='访问受限'?'本批访问受限；可从下方渠道入口手动查看。':s.label==='仅有留存线索'?'本批没有该平台的读取结果，保留已有资料。':'部分内容缺失或读取失败，请结合原文与待核项判断。'}</p>${group.leads.length?`<button class="text-btn" data-platform-open="${esc(group.id)}">查看这个平台的线索 →</button>`:'<span class="hint">本批未形成可发布线索</span>'}</article>`;}).join('')||'<div class="empty"><strong>尚无公开来源记录</strong><p>可先使用下方渠道入口找房。</p></div>'}</div><details class="panel publication-log"><summary><strong>发布记录与来源明细</strong><span class="hint">时间、原始域名、研究批次</span></summary><p>公开信息由本地 Codex 补充搜索和整理；每天两次为计划频率，需要电脑及 Codex 正在运行。GitHub Actions 校验并发布已整理摘要，网页每30秒只刷新本浏览器记录，不会自行检索房产网站。</p><p>快照状态：${esc(feed.state||'尚无来源')} · 最近构建：${dt(feed.generated_at)} · 最近检查：${dt(feed.last_attempt)} · 最近读取：${dt(feed.last_success)}</p><p>${esc(feed.reason||'尚无可证明的持续采集状态，请检查实际研究批次。')}</p><p>研究批次：${esc(research.run_id||'暂无')} · 完成 ${dt(research.completed_at)} · 最近成功 ${dt(research.last_success_at)} · 查询 ${research.query_count??'未知'} 次<br>数据版本：${esc(research.data_commit_sha||'尚未提供')}</p><div class="source-log">${(research.source_results||[]).map(x=>`<p><strong>${esc(x.source_domain||x.source_id||'来源')}</strong>：${esc(x.status||x.state||'未知')}${x.error?' / '+esc(x.error):''}${x.reason?' / '+esc(x.reason):''}</p>`).join('')}</div>${Object.entries(health).map(([id,x])=>`<p>${esc(sources.find(s=>s.id===id)?.name||id)}：读取 ${dt(x.last_success)} / 最新原始观测 ${dt(x.newest_observed_at)}${x.error?' / '+esc(x.error):''}${(x.warnings||[]).map(w=>' / '+esc(w)).join('')}</p>`).join('')}<p class="hint">检索时间、原页更新时间、发布构建时间分别保留。读取成功不能证明仍在售、区划正确或产权安全。公开摘要不会发布你的关注、笔记或核验依据。</p></details>`;
}
async function initializeLocalMode(){
 const home=$('#nav [data-view="overview"]');home.dataset.view='library';home.innerHTML='<span aria-hidden="true">◫</span>我的房源';home.title='我的房源';home.setAttribute('aria-label','我的房源');
 $('#nav [data-view="followups"]').hidden=true;
 $('#lead-comparison').hidden=true;$('#copy-lead-comparison').hidden=true;
 $('#view-compare > details').open=true;
 $('#view-compare .section-heading h2').textContent='比较我的房源';
 $('#view-compare .section-heading p').textContent='在“我的房源”勾选2—4条，比较报价、核验与跟进记录。';
 $('#privacy-help').textContent='当前为本地 Python 模式，房源、笔记和核验记录保存在本机 SQLite 数据库中；网页关闭不删除记录。请保存 SQLite 备份及来源配置。网页版浏览器记录与此数据库独立，不能互相恢复。';
 $('#save-lead-filters').hidden=true;$('#restore-lead-filters').hidden=true;
 await setView('library');
}
if(browserMode){
 for(const id of ['browser-storage-notice','sync-public-feed','public-feed-health','restore-browser'])$('#'+id).hidden=false;
 $('#backup-label').textContent='下载完整浏览器备份 JSON';
 $('#backup-help').textContent='CSV / JSON 仅是房源明细。完整浏览器备份还包含报价历史、核验、笔记、偏好和手动来源，可在其他浏览器恢复。备份含个人信息，请自行妥善保存。';
 $('#privacy-help').textContent='个人资料仅在当前浏览器 localStorage 中，不会提交到 GitHub。清理站点数据、换设备或无痕浏览会影响记录。浏览器备份与 Python SQLite 数据库不能互相恢复。';
 $('#source-mode-help').textContent='个人来源支持浏览器内监控文件，或手动同步不带密钥且允许跨域读取的公开 HTTPS JSON。公开网页和搜索线索由本地研究整理后发布，不要求房产平台提供 JSON；个人来源不会在网页关闭后运行。';
 $('#source-path-label').textContent='浏览器内保存的监控文件名';
 $('#source-interval-label').textContent='同步间隔 / 分钟（网页版不执行定时任务）';
 $('#source-enabled-label').textContent='允许手动同步此来源（网页关闭后不运行）';
 $('#source-type').options[0].textContent='浏览器内监控文件（JSON）';
 $('#digest-title').textContent='根据当前记录生成观察简报';
 $('#digest-help').textContent='网页版打开页面时生成个人简报，包含新增、报价变化和待核验事项；当前没有定时邮件或关闭网页后的个人任务。';
 $('#poll').textContent='手动同步个人来源';
 $('#sync-public-feed').onclick=e=>task(e.currentTarget,async()=>{await window.HomeWatchBrowser.syncPublicFeed();await load();toast('已检查已部署的共享快照；数据新鲜度请查看原始观测时间。');});
 document.addEventListener('click',e=>{const a=e.target.closest('a[href^="/api/"]');if(!a)return;e.preventDefault();task(a,async()=>{await window.HomeWatchBrowser.download(a.getAttribute('href'));toast('备份 / 导出已生成，请保存下载文件。');});});
 $('#restore-browser').onclick=()=>{$('#restore-form').reset();$('#restore-summary').textContent='';$('#restore-error').textContent='';$('#restore-modal').showModal();};
 $('#restore-file').onchange=()=>{const f=$('#restore-file').files[0];$('#restore-summary').textContent=f?`选定：${f.name} · ${Math.round(f.size/1024)} KB；提交前会验证格式。`:'';};
 $('#restore-form').onsubmit=e=>{e.preventDefault();task($('button[type=submit]',e.target),async()=>{const f=$('#restore-file').files[0];if(!f||!$('#restore-confirm').checked)throw Error('请选择备份并确认替换。');if(f.size>window.HomeWatchBrowser.maxBackupBytes)throw Error('备份不得超过6MiB。');try{await window.HomeWatchBrowser.restore(await f.text());$('#restore-modal').close();state.settingsDirty=false;state.sourceDirty=false;state.selected.clear();state.leadSelected.clear();state.filtersInitialized=false;await load();toast('浏览器备份已恢复。');}catch(err){$('#restore-error').textContent=err.message;throw err;}});};
}else initializeLocalMode().catch(e=>toast(e.message,true));
